package demo.brain;
import org.junit.jupiter.api.Test;
import com.fasterxml.jackson.databind.ObjectMapper;
import static org.assertj.core.api.Assertions.*;
import java.util.*;

class CityTrainingTest {
 @Test void snapshotsDoNotShareMutableContributionSets(){var t=new CityTraining();t.badge("a","최초 단서 발견");var snapshot=t.view("a",1);t.badge("a","협업 지원");assertThat(new ObjectMapper().valueToTree(snapshot).path("badges").path("a").size()).isEqualTo(1);}
 final ObjectMapper json=new ObjectMapper();long now=1_000_000;
 void act(CityTraining t,String who,String op,String value){t.apply(who,who,json.valueToTree(Map.of("missionId",t.id,"revision",t.revision,"op",op,"value",value)),now);}
 void role(CityTraining t,String role){act(t,"solo","role",role);}
 CityTraining investigated(){var t=new CityTraining();act(t,"solo","start","");for(String clue:List.of("pool","database","deploy","timeout")){role(t,CityTraining.CLUE_ROLE.get(clue));act(t,"solo","inspect",CityTraining.CLUE_ZONE.get(clue));act(t,"solo","share",clue);}act(t,"solo","vote","leak");act(t,"solo","diagnose","");return t;}
 void execute(CityTraining t,String plan){role(t,"복구 담당");act(t,"solo","test",plan);act(t,"solo","request",plan);role(t,"상황 책임자");act(t,"solo","approve","");role(t,"복구 담당");act(t,"solo","execute","");}
 @Test void soloNeedsEvidenceRoleApprovalAndStableVerification(){var initial=new CityTraining();assertThatThrownBy(()->act(initial,"solo","execute","")).isInstanceOf(IllegalStateException.class);var t=investigated();assertThat(t.stage).isEqualTo("TRIAL");final var ready=t;assertThatThrownBy(()->act(ready,"solo","approve","")).isInstanceOf(IllegalStateException.class);execute(t,"rollback");assertThat(t.stage).isEqualTo("EXECUTING");now+=8000;t.tick(now);assertThat(t.stage).isEqualTo("VERIFY");role(t,"관제 담당");assertThatThrownBy(()->act(ready,"solo","verify","")).hasMessageContaining("안정화");now+=3000;act(t,"solo","verify","");assertThat(t.stage).isEqualTo("RESULT");assertThat(t.finished-t.started).isEqualTo(11000);assertThat(t.badges.get("solo")).contains("정확한 원인 분석","최초 단서 발견");}
 @Test void restartAndBypassCannotProduceFalseSuccess(){for(String plan:List.of("restart","bypass")){var t=investigated();execute(t,plan);now+=8000;t.tick(now);role(t,"관제 담당");now+=3000;act(t,"solo","verify","");assertThat(t.stage).isEqualTo("TRIAL");assertThat(t.approved).isFalse();assertThat(t.feedback).contains("검증 실패");assertThat(t.finished).isZero();}}
 @Test void deadlineIsServerAuthoritativeAndCanContinueWithoutTimeLimit(){var t=new CityTraining();act(t,"solo","start","");long started=t.started;t.tick(started+300001);assertThat(t.stage).isEqualTo("TIMEOUT");assertThat(t.finished).isEqualTo(started+300000);now=started+301000;act(t,"solo","continue","");assertThat(t.stage).isEqualTo("CLUES");t.tick(now+99_000_000);assertThat(t.stage).isEqualTo("CLUES");assertThat(t.overtime).isTrue();}
 @Test void oldMissionAndConcurrentRevisionCannotAdvanceNewRound(){var t=new CityTraining();var old=json.valueToTree(Map.of("missionId",t.id,"revision",t.revision,"op","start"));t.apply("a","가상 A",old,now);assertThatThrownBy(()->t.apply("b","가상 B",old,now)).hasMessageContaining("먼저 반영");t.tick(now+300001);act(t,"a","reset","");assertThat(t.stage).isEqualTo("LOBBY");assertThatThrownBy(()->t.apply("a","가상 A",old,now)).hasMessageContaining("먼저 반영");assertThat(t.shared).isEmpty();assertThat(t.badges).isEmpty();assertThat(t.trials).isEmpty();}
 @Test void privateCluesRequireRoleAndOnlyShareOnce(){var t=new CityTraining();act(t,"a","start","");act(t,"a","inspect","app");assertThat(t.privateClues).isEmpty();assertThatThrownBy(()->act(t,"a","share","deploy")).hasMessageContaining("조사");act(t,"a","role","분석 담당");act(t,"a","inspect","app");assertThat(t.view("b",now).get("privateClues")).isEqualTo(List.of());act(t,"a","share","deploy");assertThat(t.view("b",now).get("clues").toString()).contains("v2.8");assertThatThrownBy(()->act(t,"a","share","deploy")).hasMessageContaining("이미");assertThat(t.shared).hasSize(1);}
 @Test void modelIsDeterministicAndWrongCauseRemainsUnconfirmed(){assertThat(CityTraining.simulate("rollback")).isEqualTo(CityTraining.simulate("rollback"));assertThat(CityTraining.simulate("restart").get("safe")).isEqualTo(false);var t=investigated();t.stage="CAUSE";act(t,"solo","vote","database");act(t,"solo","diagnose","");assertThat(t.stage).isEqualTo("CAUSE");assertThat(t.feedback).contains("다시 확인");}
}

